#include <FFPMscT.hpp>

#include <cmath>
#include <complex>

#include <FArray.hpp>
#include <W1jet.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.21
std::complex<double> FFPMscT(int j1, int j2, int j3, int j4, int j5, int j6,
                              FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> FFPMscT_value;
  double Delta3, delta12, delta56;

  // Statement functions
  auto zab2 = [&za, &zb](int j1, int j2, int j3, int j4) {
    return za(j1, j2) * zb(j2, j4) + za(j1, j3) * zb(j3, j4);
  };
  auto zab = [&za, &zb](int j1, int j2, int j3) {
    return za(j1, j2) * zb(j2, j3);
  };
  auto zba = [&za, &zb](int j1, int j2, int j3) {
    return zb(j1, j2) * za(j2, j3);
  };
  auto zb22b = [&zb, &zab2](int j1, int j2, int j3, int j4, int j5, int j6) {
    return
      zb(j1, j2) * zab2(j2, j4, j5, j6) + zb(j1, j3) * zab2(j3, j4, j5, j6);
  };
  // End statement functions

  Delta3 = std::pow(s(j1, j2), 2) + std::pow(s(j3, j4), 2) + std::pow(s(j5, j6), 2)
    - 2 * s(j1, j2) * s(j3, j4) - 2 * s(j3, j4) * s(j5, j6) - 2 * s(j5, j6) * s(j1, j2);
  delta12 = s(j1, j2) - s(j3, j4) - s(j5, j6);
  delta56 = s(j5, j6) - s(j1, j2) - s(j3, j4);

  FFPMscT_value =
    3 * s(j1, j2) * zb(j4, j6) * za(j5, j6) * zab2(j4, j1, j2, j3)
      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4) * std::pow(Delta3, 2))
    * (za(j1, j2) * zb(j5, j6)
      * (zab(j5, j6, j1) * delta56 - zab(j5, j2, j1) * delta12)
      + t(j1, j2, j4) * (zab(j2, j5, j6) * delta56 - zab(j2, j1, j6) * delta12))

    + za(j1, j2) * zb(j4, j6)
      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4) * Delta3)
    * (-zb(j1, j2) * za(j5, j6)
      * (3 * zab2(j4, j1, j2, j3) * zab2(j2, j1, j3, j6)
        - za(j2, j4) * zb(j3, j6) * (t(j1, j2, j3) - t(j1, j2, j4)))

      + zab2(j4, j1, j2, j3)
        * (zab(j5, j2, j1) * delta12 - zab(j5, j6, j1) * delta56
          + t(j1, j2, j3) * zab2(j5, j2, j4, j1) - t(j1, j2, j4) * zab2(j5, j2, j3, j1))

      + za(j4, j5) * t(j1, j2, j3) * (zb22b(j1, j3, j4, j1, j2, j3)
        - zba(j1, j2, j4) * zb(j4, j3))
      - zab2(j4, j1, j2, j3) * za(j3, j5) * t(j1, j2, j3)
        * (zb22b(j1, j3, j4, j1, j2, j4) - zba(j1, j2, j3) * zb(j3, j4))
        / zab2(j3, j1, j2, j4))

    - zab(j2, j1, j3) * zab(j5, j4, j6)
      / (zab2(j3, j1, j2, j4) * zab2(j1, j2, j3, j4))

    + 3 * zab(j1, j5, j6) * zab2(j4, j1, j2, j3) / (zab2(j1, j2, j3, j4) * std::pow(Delta3, 2))
    * (zab(j2, j1, j3) * (zab(j5, j2, j1) * delta12 - zab(j5, j6, j1) * delta56)
      + zab(j1, j2, j3) * (zab(j5, j6, j2) * delta56 - zab(j5, j1, j2) * delta12)
        * zab2(j2, j3, j4, j1) / zab2(j1, j3, j4, j2))

    + za(j1, j5) / (zab2(j1, j2, j3, j4) * Delta3)
    * (-zb(j1, j3)
      * (zab(j2, j1, j3) * zab(j4, j5, j6) + zab(j4, j2, j3) * zab(j2, j5, j6)
        - zab2(j4, j1, j2, j3) * (zab(j2, j1, j6) - zab(j2, j5, j6)))

      + zb(j2, j3) * zab2(j2, j3, j4, j1) / zab2(j1, j3, j4, j2)
        * (3 * zab(j1, j5, j6) * zab(j4, j2, j3) - zab(j1, j2, j6) * zab2(j4, j1, j2, j3)
          + zb(j2, j3) * za(j1, j4) * zab(j1, j5, j6) * (t(j2, j3, j4) - t(j1, j3, j4))
            / zab2(j1, j3, j4, j2)));

  FFPMscT_value = FFPMscT_value; // @coverage-probe
  return FFPMscT_value;
}

extern "C" {
  std::complex<double> FFPMscT_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                                        std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return FFPMscT(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
